/**
 * One photograph per monitored city, with the attribution its licence
 * requires.
 *
 * Generated by `node scripts/fetch-city-images.mjs` from Wikipedia's landmark
 * articles (see that file for how a candidate is chosen and why it is not a
 * Commons full-text search). Agra is pinned by hand to the Taj Mahal frame the
 * site was designed around.
 *
 * Attribution is not optional decoration here: most of these are CC BY-SA,
 * which requires the author, the licence, and a path back to the original.
 * The hero renders all three, and `Hero.tsx` is the only consumer that may
 * drop them — it may not.
 */

import json from "./city-images.json";

export interface CityImage {
  slug: string;
  src: string;
  srcSet: string;
  /** 20px inline WebP, so a swap paints something on the first frame. */
  lqip: string;
  /** What the photograph is of, in words. */
  title: string;
  artist: string;
  license: string;
  licenseUrl: string;
  sourceUrl: string;
  /** The Wikipedia article it was sourced from. */
  source: string;
  /** Where to anchor the crop, e.g. "center 58%". */
  objectPosition: string;
}

export const CITY_IMAGES: Record<string, CityImage> = json as Record<
  string,
  CityImage
>;

/** The Taj frame — the hero's fallback when a city has no photograph yet. */
export const DEFAULT_CITY_IMAGE: CityImage = CITY_IMAGES.Agra;

export function imageForCity(cityName: string | undefined): CityImage {
  if (!cityName) return DEFAULT_CITY_IMAGE;
  return CITY_IMAGES[cityName] ?? DEFAULT_CITY_IMAGE;
}

/**
 * Warm an image the reader is *about* to ask for.
 *
 * The city switcher calls this as the highlight moves through the list, so by
 * the time someone presses Enter the photograph is usually already decoded
 * and the cross-fade has nothing to wait for. Cheap: the browser dedupes it
 * against its own cache, and nothing is kept.
 */
export function preloadCityImage(cityName: string): void {
  const image = CITY_IMAGES[cityName];
  if (!image || typeof Image === "undefined") return;
  const img = new Image();
  img.sizes = "100vw";
  img.srcset = image.srcSet;
  img.src = image.src;
}
